def solve(text: str) -> str:
    lines = text.split('\n')
    h, w, k = map(int, lines[0].split())
    grid = [list(lines[1 + i]) for i in range(h)]

    for _ in range(k):
        new = [['.'] * w for _ in range(h)]
        for r in range(h):
            for c in range(w):
                n = 0
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        rr, cc = r + dr, c + dc
                        if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == '#':
                            n += 1
                if grid[r][c] == '#':
                    new[r][c] = '#' if n == 2 or n == 3 else '.'
                else:
                    new[r][c] = '#' if n == 3 else '.'
        grid = new

    return '\n'.join(''.join(row) for row in grid)
```

**`games/sub.py`**
```python
def solve(text: str) -> str:
    lines = text.split()
    n = int(lines[0])
    k = int(lines[1])
    steps = [int(x) for x in lines[2:2 + k]]

    win = [False] * (n + 1)
    for i in range(1, n + 1):
        for s in steps:
            if s <= i and not win[i - s]:
                win[i] = True
                break

    if not win[n]:
        return 'LOSE'
    for s in sorted(steps):
        if s <= n and not win[n - s]:
            return 'WIN %d' % s
    return 'LOSE'
```

**`games/nim.py`**
```python
def solve(text: str) -> str:
    lines = text.split()
    m = int(lines[0])
    piles = [int(x) for x in lines[1:1 + m]]

    x = 0
    for p in piles:
        x ^= p

    if x == 0:
        return 'LOSE'
    for idx in range(m):
        p = piles[idx]
        target = p ^ x
        if target < p:
            return 'WIN %d %d' % (idx + 1, p - target)
    return 'LOSE'
```

**`games/wythoff.py`**
```python
def _losing(limit):
    """Wythoff P-positions as a set, keyed with both pile orders."""
    if limit < 0:
        limit = 0
    loses = set()
    phi = (1 + 5 ** 0.5) / 2.0
    n = 0
    while True:
        xi = int(n * phi)
        yi = xi + n
        if xi > limit:
            break
        loses.add((xi, yi))
        loses.add((yi, xi))
        n += 1
    return loses


def solve(text: str) -> str:
    data = text.split()
    a = int(data[0])
    b = int(data[1])
    loses = _losing(max(a, b))

    if (a, b) in loses:
        return 'LOSE'

    for i in range(a + 1):
        for j in range(b + 1):
            if i == 0 and j == 0:
                continue
            if i > 0 and j > 0 and i != j:
                continue
            if (a - i, b - j) in loses:
                return 'WIN %d %d' % (i, j)

    return 'LOSE'
```

